import json
import os
import time
import urllib.request


DOMAIN = "[workspace-id].cn-beijing.maas.aliyuncs.com"
MODEL = "kling/kling-v4-omni-reference-video-generation"
API_KEY = os.environ["DASHSCOPE_API_KEY"]


def request(method, path, payload=None):
    headers = {
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json",
    }

    if method == "POST":
        headers["X-DashScope-Async"] = "enable"

    body = None if payload is None else json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        f"https://[workspace-id].cn-beijing.maas.aliyuncs.com{path}",
        data=body,
        method=method,
        headers=headers,
    )

    with urllib.request.urlopen(req, timeout=90) as response:
        return json.loads(response.read().decode("utf-8"))


created = request(
    "POST",
    "/api/v1/services/aigc/video-generation/video-synthesis",
    {
        "model": MODEL,
        "input": {
            "prompt": "一只小猫在月光下奔跑",
        },
        "parameters": {
            "mode": "std",
            "aspect_ratio": "16:9",
            "duration": 3,
            "watermark": True,
        },
    },
)

task_id = created.get("output", {}).get("task_id")
if not task_id:
    raise RuntimeError(f"未返回任务 ID：{created}")

print(f"任务已创建：{task_id}", flush=True)

for _ in range(80):
    result = request("GET", f"/api/v1/tasks/{task_id}")
    status = result.get("output", {}).get("task_status")

    if status == "SUCCEEDED":
        print(json.dumps(result, ensure_ascii=False, indent=2))
        break

    if status in {"FAILED", "CANCELED", "UNKNOWN"}:
        raise RuntimeError(f"任务 {task_id} 已结束，状态为 {status}：{result}")

    time.sleep(15)
else:
    raise TimeoutError(f"任务 {task_id} 在 20 分钟内未完成。")

