import https from "node:https";

// 请在环境变量中配置 DASHSCOPE_API_KEY。
const DOMAIN = "[workspace-id].cn-beijing.maas.aliyuncs.com";
const MODEL = "kling/kling-v4-omni-reference-video-generation";
const API_KEY = process.env.DASHSCOPE_API_KEY;

if (!API_KEY) {
  throw new Error("请先设置环境变量 DASHSCOPE_API_KEY。");
}

function request(method, path, payload) {
  return new Promise((resolve, reject) => {
    const body = payload ? JSON.stringify(payload) : undefined;
    const headers = {
      Authorization: `Bearer ${API_KEY}`,
    };

    if (method === "POST") {
      headers["X-DashScope-Async"] = "enable";
    }
    if (body) {
      headers["Content-Type"] = "application/json";
      headers["Content-Length"] = Buffer.byteLength(body);
    }

    const req = https.request(
      {
        hostname: DOMAIN,
        path,
        method,
        headers,
      },
      (res) => {
        let text = "";

        res.on("data", (chunk) => {
          text += chunk;
        });

        res.on("end", () => {
          let result;
          try {
            result = JSON.parse(text);
          } catch {
            reject(new Error(`HTTP ${res.statusCode}：${text}`));
            return;
          }

          if (res.statusCode < 200 || res.statusCode >= 300) {
            reject(new Error(`HTTP ${res.statusCode}：${JSON.stringify(result)}`));
            return;
          }

          resolve(result);
        });
      },
    );

    req.on("error", reject);

    if (body) {
      req.write(body);
    }
    req.end();
  });
}

const created = await request(
  "POST",
  "/api/v1/services/aigc/video-generation/video-synthesis",
  {
    model: MODEL,
    input: {
      prompt: "一只小猫在月光下奔跑",
    },
    parameters: {
      mode: "std",
      aspect_ratio: "16:9",
      duration: 3,
      watermark: true,
    },
  },
);

const taskId = created.output?.task_id;
if (!taskId) {
  throw new Error(`未返回任务 ID：${JSON.stringify(created)}`);
}

console.log(`任务已创建：${taskId}`);

for (let attempt = 0; attempt < 80; attempt += 1) {
  const result = await request("GET", `/api/v1/tasks/${taskId}`);
  const status = result.output?.task_status;

  if (status === "SUCCEEDED") {
    console.log(JSON.stringify(result, null, 2));
    process.exit(0);
  }

  if (["FAILED", "CANCELED", "UNKNOWN"].includes(status)) {
    throw new Error(`任务 ${taskId} 已结束，状态为 ${status}：${JSON.stringify(result)}`);
  }

  await new Promise((resolve) => setTimeout(resolve, 15000));
}

throw new Error(`任务 ${taskId} 在 20 分钟内未完成。`);

